-- Extensions first: the generated migration that follows uses `vector` for
-- embeddings and will use `pg_trgm`/full-text once search lands. Generated by
-- `drizzle-kit generate --custom`, kept ahead of the schema migration because
-- drizzle-kit does not emit CREATE EXTENSION itself.
--
-- One statement per batch: drizzle's migrator splits on the breakpoint marker,
-- so without them the driver is handed four statements as one string, which the
-- Neon HTTP path rejects. 0001 depends on `vector` already existing.
CREATE EXTENSION IF NOT EXISTS vector;--> statement-breakpoint
CREATE EXTENSION IF NOT EXISTS pg_trgm;--> statement-breakpoint
CREATE EXTENSION IF NOT EXISTS citext;--> statement-breakpoint
CREATE EXTENSION IF NOT EXISTS pgcrypto;
